        AddDungeonEntrance("dungeon_crypt", gg_unit_n03N_0077)
        AddDungeonEntrance("dungeon_ancient_ruins", gg_unit_n03P_0078)


        DungeonOpen("dungeon_secret_crypt")
        DungeonOpen("dungeon_cave")
        DungeonOpen("dungeon_crypt")
        DungeonOpen("dungeon_ancient_ruins")


        RegisterTestCommand("do", function()
            DungeonOpen("test_dungeon")
            DungeonOpen("dungeon_cave")
        end)

        RegisterTestCommand("dc", function()
            DungeonClose("test_dungeon")
        end)

        RegisterTestCommand("dopen", function()
            DungeonOpenGate(DungeonTemplates["test_dungeon"].gates[1])
            DungeonOpenGate(DungeonTemplates["test_dungeon"].gates[2])
        end)

        RegisterTestCommand("dclose", function()
            DungeonCloseGate(DungeonTemplates["test_dungeon"].gates[1])
            DungeonCloseGate(DungeonTemplates["test_dungeon"].gates[2])
        end)

        RegisterTestCommand("sk", function()
            DungeonTemplates["test_dungeon"].current_wave = 6
            ForGroup(DungeonTemplates["test_dungeon"].monster_group, function()
                KillUnit(GetEnumUnit())
            end)
        end)

    end

end